using Meziantou.Framework.JavaScriptEngine.Intl.Data;

namespace Meziantou.Framework.JavaScriptEngine.Intl;

/// <summary>The word lists of ICU used by the word segmentation of <c>Intl.Segmenter</c>, one chunk of <c>dictionaries.bin</c> each.</summary>
internal enum WordDictionaryKind
{
    /// <summary>Chinese and Japanese (<c>cjdict.txt</c>): the words have a cost.</summary>
    ChineseJapanese,
    Thai,
    Lao,
    Khmer,
    Burmese,
}

/// <summary>
/// The word lists embedded in the engine (<c>Intl/Data/dictionaries.bin</c>, generated by
/// tools/Meziantou.Framework.JavaScriptEngine.Data.Generator from the data of ICU). Nothing is read before the first
/// segmentation of a text of the script of a list, and a list is decompressed and loaded once. The instances are thread-safe.
/// </summary>
internal sealed partial class WordDictionaries
{
    internal const string ResourceName = "Meziantou.Framework.JavaScriptEngine.Intl.Data.dictionaries.bin";

    private static WordDictionaries? s_default;

    private readonly CldrChunkedFile _file;
    private readonly WordDictionary?[] _dictionaries;

    internal WordDictionaries(CldrChunkedFile file)
    {
        if (file.ChunkCount != (int)WordDictionaryKind.Burmese + 1)
            throw new InvalidDataException("The word lists are invalid");

        _file = file;
        _dictionaries = new WordDictionary?[file.ChunkCount];
    }

    /// <summary>Gets the word lists embedded in the engine.</summary>
    public static WordDictionaries Default => Volatile.Read(ref s_default) ?? CldrData.InitializeOnce(ref s_default, new WordDictionaries(CldrChunkedFile.FromResource(ResourceName)));

    internal CldrChunkedFile File => _file;

    /// <summary>Gets a word list, loading it on first use.</summary>
    public WordDictionary Get(WordDictionaryKind kind)
    {
        var index = (int)kind;
        return Volatile.Read(ref _dictionaries[index]) ?? CldrData.InitializeOnce(ref _dictionaries[index], WordDictionary.Load(_file.ReadChunk(index)));
    }
}
